function signal(initial) {
  let value = initial;
  const getter = () => value;
  getter.set = (v) => { value = v; };
  getter.update = (fn) => { value = fn(value); };
  return getter;
}

function computed(fn) {
  return () => fn();
}

class BehaviorSubject {
  #value;
  #observers = new Set();
  constructor(initial) { this.#value = initial; }
  get value() { return this.#value; }
  next(v) {
    this.#value = v;
    this.#observers.forEach((o) => o(v));
  }
  subscribe(observer) {
    this.#observers.add(observer);
    observer(this.#value);
    return () => this.#observers.delete(observer);
  }
}

class Container {
  #factories = new Map();
  #instances = new Map();
  #resolving = new Set();
  register(token, factory) {
    this.#factories.set(token, factory);
  }
  resolve(token) {
    if (this.#instances.has(token)) return this.#instances.get(token);
    const factory = this.#factories.get(token);
    if (!factory) throw new Error('Token inconnu : ' + String(token));
    if (this.#resolving.has(token)) throw new Error('Dépendance circulaire : ' + String(token));
    this.#resolving.add(token);
    try {
      const instance = factory(this);
      this.#instances.set(token, instance);
      return instance;
    } finally {
      this.#resolving.delete(token);
    }
  }
}

