class Observable {
  constructor(subscribeFn) { this._subscribe = subscribeFn; }
  subscribe(next) {
    const cleanup = this._subscribe({ next });
    return () => { if (typeof cleanup === 'function') cleanup(); };
  }
  pipe(...operators) {
    return operators.reduce((source, op) => op(source), this);
  }
}

function map(fn) {
  return (source) => new Observable((observer) => {
    const unsubscribe = source.subscribe((v) => observer.next(fn(v)));
    return unsubscribe;
  });
}

function isBalanced(str) {
  const pairs = { ')': '(', ']': '[', '}': '{' };
  const stack = [];
  for (const ch of str) {
    if ('([{'.includes(ch)) stack.push(ch);
    else if (ch in pairs && stack.pop() !== pairs[ch]) return false;
  }
  return stack.length === 0;
}

function chunk(arr, size) {
  const result = [];
  for (let i = 0; i < arr.length; i += size) result.push(arr.slice(i, i + size));
  return result;
}

function updateTodo(state, id, patch) {
  return { ...state, todos: state.todos.map((t) => (t.id === id ? { ...t, ...patch } : t)) };
}
